use Plack::Util;
use strict;
use warnings;
use parent qw(Exporter);
use Carp ();
use HTTP::Status qw(status_message);
use URI::Escape ();
use Scalar::Util ();
require HTTP::Response
sub req_to_psgi {
my $req = shift;
[MASK]
