use Scalar::Util ();
sub response_cb {
    my($res, $cb) = @_;
    my @headers = @{ $res->[1] };
    if ( $res->[2] && ref $res->[2] eq 'ARRAY' ) {
        push @headers, @{ $res->[2] };
    }
    if ( @headers ) {
        my $content = $res->[2];
        if ( !ref $content ) {
            unshift @headers, 'Content-Length' => length $content;
        }
        elsif ( Scalar::Util::blessed($content) && $content->can('getlines') ) {
            unshift @headers, 'Content-Length' => do {
                local $/;
                seek $content, 0, 0;
                length <$content>;
            };
        }
    }
    elsif ( defined $res->[2] ) {
        unshift @headers, 'Content-Length' => length $res->[2];
    }
    else {
        unshift @headers, 'Content-Length' => 0;
    }
    return $cb->( $res->[0], \@headers, $res->[2] );
}
